export class ColorTheoryRulesEngine {
  public getCoordinationBySuit(suitColorFamily: string): ColorCoordinationSpec[] {
    return COLOR_COORDINATION_MATRIX_DATABASE.filter(c => c.suitColorFamily.toLowerCase().includes(suitColorFamily.toLowerCase()));
  }
}
export const colorTheoryRulesEngine = new ColorTheoryRulesEngine();
